package com.chx.claims.identity.security;
import com.chx.claims.identity.domain.User; import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.*; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class JwtService { private final byte[] secret; public JwtService(@Value("${JWT_SECRET:change-this-development-secret-to-at-least-32-characters}") String s){secret=s.getBytes(StandardCharsets.UTF_8);} public String issue(User u){String h=enc("{\"alg\":\"HS256\",\"typ\":\"JWT\"}"),p=enc("{\"sub\":\""+u.getId()+"\",\"email\":\""+u.getEmail()+"\",\"role\":\""+u.getRole()+"\",\"exp\":"+(Instant.now().getEpochSecond()+3600)+"}");return h+"."+p+"."+sign(h+"."+p);} private String enc(String s){return Base64.getUrlEncoder().withoutPadding().encodeToString(s.getBytes(StandardCharsets.UTF_8));} private String sign(String v){try{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret,"HmacSHA256"));return Base64.getUrlEncoder().withoutPadding().encodeToString(m.doFinal(v.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}} }
